import React, { useState } from 'react';
import { MapContainer, TileLayer, CircleMarker } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { MapPin, Thermometer, Eye } from 'lucide-react';

const SatelliteImagery = ({ satelliteData, cityName, center, heatZones = [] }) => {
  const [activeView, setActiveView] = useState('thermal');

  if (!satelliteData) {
    return (
      <div className="flex items-center justify-center h-64 bg-gray-100 rounded-lg">
        <p className="text-gray-600">Satellite imagery not available</p>
      </div>
    );
  }

  const views = [
    { id: 'thermal', name: 'Thermal View', icon: Thermometer, color: 'bg-red-500' },
    { id: 'heat_map', name: 'Heat Map', icon: MapPin, color: 'bg-orange-500' },
    { id: 'before_after', name: 'Before/After', icon: Eye, color: 'bg-blue-500' }
  ];

// Simple Before/After slider component
function BeforeAfterSlider({ beforeSrc, afterSrc }) {
  const [pos, setPos] = useState(50); // percentage

  return (
    <div className="relative w-full h-56 md:h-64 rounded-lg border overflow-hidden select-none">
      <img src={beforeSrc} alt="Before" className="absolute inset-0 w-full h-full object-cover" />
      <div style={{ width: `${pos}%` }} className="absolute inset-0 overflow-hidden">
        <img src={afterSrc} alt="After" className="w-full h-full object-cover" />
      </div>
      {/* Handle */}
      <div
        className="absolute top-0 bottom-0"
        style={{ left: `${pos}%`, transform: 'translateX(-50%)' }}
      >
        <div className="w-1 h-full bg-white shadow" />
        <div className="w-6 h-6 rounded-full bg-white shadow -mt-3 mx-auto border" />
      </div>
      {/* Interaction layer */}
      <input
        type="range"
        min="0"
        max="100"
        value={pos}
        onChange={(e) => setPos(Number(e.target.value))}
        className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize"
      />
      <div className="absolute top-2 left-2 bg-green-600 text-white px-2 py-1 rounded text-xs">Before</div>
      <div className="absolute top-2 right-2 bg-red-600 text-white px-2 py-1 rounded text-xs">After</div>
    </div>
  );
}

  const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

  // Build URLs: prefer live Google Static Maps if API key is present, else use high-quality placeholders
  const beforeUrl = apiKey
    ? `https://maps.googleapis.com/maps/api/staticmap?center=${encodeURIComponent(cityName)}&zoom=11&size=320x200&maptype=satellite&key=${apiKey}`
    : 'https://images.unsplash.com/photo-1461319805560-d7d2a72c2d16?q=80&w=800&auto=format&fit=crop';
  const afterUrl = apiKey
    ? `https://maps.googleapis.com/maps/api/staticmap?center=${encodeURIComponent(cityName)}&zoom=11&size=320x200&maptype=roadmap&key=${apiKey}`
    : 'https://images.unsplash.com/photo-1482192505345-5655af888cc4?q=80&w=800&auto=format&fit=crop';

  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold text-gray-800">Satellite Imagery Analysis</h3>

      {/* View selector */}
      <div className="flex space-x-2 mb-4">
        {views.map((view) => {
          const Icon = view.icon;
          return (
            <button
              key={view.id}
              onClick={() => setActiveView(view.id)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-lg transition-colors ${
                activeView === view.id
                  ? 'bg-blue-100 text-blue-700 border-2 border-blue-300'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <Icon className="w-4 h-4" />
              <span className="text-sm font-medium">{view.name}</span>
            </button>
          );
        })}
      </div>

      {/* Image display */}
      <div className="relative">
        {activeView === 'thermal' && (
          <div className="space-y-4">
            <div className="relative rounded-lg overflow-hidden border" style={{height: 320}}>
              <MapContainer center={[center.lat, center.lng]} zoom={12} style={{height: '100%', width: '100%'}}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution="&copy; OpenStreetMap" />
                {heatZones.map((z, idx) => {
                  const intensity = z.intensity || 0.5;
                  const color = intensity > 0.8 ? '#dc2626' : intensity > 0.6 ? '#ea580c' : intensity > 0.4 ? '#eab308' : '#16a34a';
                  const radius = 80 + intensity * 120;
                  return (
                    <CircleMarker
                      key={idx}
                      center={[z.lat, z.lng]}
                      pathOptions={{ color, fillColor: color, fillOpacity: 0.35 }}
                      radius={radius / 20}
                    />
                  );
                })}
              </MapContainer>
              <div className="absolute top-2 left-2 bg-black bg-opacity-70 text-white px-3 py-1 rounded-lg text-sm">
                🔥 Thermal-style Intensity (Leaflet)
              </div>
            </div>
            <p className="text-sm text-gray-600">
              Thermal satellite imagery showing heat distribution across {cityName}. 
              Red areas indicate higher surface temperatures.
            </p>
          </div>
        )}

        {activeView === 'heat_map' && (
          <div className="space-y-4">
            <div className="relative rounded-lg overflow-hidden border" style={{height: 320}}>
              <MapContainer center={[center.lat, center.lng]} zoom={12} style={{height: '100%', width: '100%'}}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution="&copy; OpenStreetMap" />
              </MapContainer>
              <div className="absolute top-2 left-2 bg-black bg-opacity-70 text-white px-3 py-1 rounded-lg text-sm">
                🌡️ Heat Map (Leaflet Heat)
              </div>
            </div>
            <p className="text-sm text-gray-600">
              Heat map overlay showing urban heat island intensity. Warmer colors indicate areas with higher heat retention.
            </p>
          </div>
        )}

        {activeView === 'before_after' && (
          <div className="space-y-4">
            <BeforeAfterSlider 
              beforeSrc={satelliteData?.before_after?.before || beforeUrl}
              afterSrc={satelliteData?.before_after?.after || afterUrl}
            />
            <p className="text-sm text-gray-600">
              Before and after comparison showing urban development impact on local climate. 
              Notice the increase in impervious surfaces and reduction in green cover.
            </p>
          </div>
        )}
      </div>

      {/* Analysis insights */}
      <div className="bg-blue-50 rounded-lg p-4">
        <h4 className="font-semibold text-blue-900 mb-2">📊 Analysis Insights</h4>
        <ul className="text-sm text-blue-800 space-y-1">
          <li>• Urban areas show 3-5°C higher temperatures than surrounding rural areas</li>
          <li>• Industrial zones exhibit the highest heat intensity</li>
          <li>• Green spaces provide significant cooling effects</li>
          <li>• Building density correlates with heat retention</li>
        </ul>
      </div>
    </div>
  );
};

export default SatelliteImagery;

// Simple Before/After slider component
function BeforeAfterSlider({ beforeSrc, afterSrc }) {
  const [pos, setPos] = useState(50); // percentage

  return (
    <div className="relative w-full h-56 md:h-64 rounded-lg border overflow-hidden select-none">
      <img src={beforeSrc} alt="Before" className="absolute inset-0 w-full h-full object-cover" />
      <div style={{ width: `${pos}%` }} className="absolute inset-0 overflow-hidden">
        <img src={afterSrc} alt="After" className="w-full h-full object-cover" />
      </div>
      {/* Handle */}
      <div
        className="absolute top-0 bottom-0"
        style={{ left: `${pos}%`, transform: 'translateX(-50%)' }}
      >
        <div className="w-1 h-full bg-white shadow" />
        <div className="w-6 h-6 rounded-full bg-white shadow -mt-3 mx-auto border" />
      </div>
      {/* Interaction layer */}
      <input
        type="range"
        min="0"
        max="100"
        value={pos}
